{
  "findings": [
    {
      "check_id": "CKV_AZURE_221",
      "title": "Ensure that Azure Function App public network access is disabled",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "Public network access is enabled by default, which can expose the Function App to the internet and increase the attack surface."
    },
    {
      "check_id": "CKV_AZURE_67",
      "title": "Ensure that 'HTTP Version' is the latest, if used to run the Function app",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The HTTP version is not explicitly set, which may result in the use of an outdated version, potentially leading to performance or security issues."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Ensure that function apps enables Authentication",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "Authentication is not enabled, which can allow unauthorized access to the Function App."
    },
    {
      "check_id": "CKV_AZURE_70",
      "title": "Ensure that Function apps is only accessible over HTTPS",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "HTTPS-only access is not enforced, which can allow insecure connections over HTTP."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n\n  https_only                 = true\n  public_network_access_enabled = false\n  site_config {\n    http2_enabled = true\n  }\n  auth_settings {\n    enabled = true\n  }\n}",
  "fix_summary": "Disabled public network access, enforced HTTPS-only access, enabled HTTP/2, and added authentication settings to secure the Azure Function App."
}
